67: class CdpClient {
68:   constructor(wsUrl) {
69:     this.wsUrl = wsUrl;
70:     this.ws = null;
71:     this.id = 1;
72:     this.pending = new Map();
73:     this.eventListeners = new Map();
74:   }
75: 
76:   connect() {
77:     return new Promise((resolve, reject) => {
78:       this.ws = new WebSocket(this.wsUrl);
79:       this.ws.onopen = () => resolve();
80:       this.ws.onerror = (err) => reject(err);
81:       this.ws.onmessage = (event) => {
82:         try {
83:           const msg = JSON.parse(event.data);
84:           if (msg.id && this.pending.has(msg.id)) {
85:             const { resolve: res, reject: rej } = this.pending.get(msg.id);
86:             this.pending.delete(msg.id);
87:             if (msg.error) rej(new Error(msg.error.message || JSON.stringify(msg.error)));
88:             else res(msg.result);
89:           } else if (msg.method) {
90:             const handlers = this.eventListeners.get(msg.method) || [];
91:             handlers.forEach(fn => fn(msg.params));
92:           }
93:         } catch (e) {
94:           console.error('CDP message parse error:', e);
95:         }
96:       };
97:     });
98:   }
99: 
100:   send(method, params = {}) {
101:     return new Promise((resolve, reject) => {
102:       const msgId = this.id++;
103:       this.pending.set(msgId, { resolve, reject });
104:       this.ws.send(JSON.stringify({ id: msgId, method, params }));
105:     });
106:   }
107: 
108:   on(method, handler) {
109:     if (!this.eventListeners.has(method)) {
110:       this.eventListeners.set(method, []);
111:     }
112:     this.eventListeners.get(method).push(handler);
113:   }
114: 
115:   async evaluate(expression, awaitPromise = true) {
116:     const res = await this.send('Runtime.evaluate', {
117:       expression,
118:       awaitPromise,
