120:     });
121:     if (res.exceptionDetails) {
122:       throw new Error(res.exceptionDetails.exception ? res.exceptionDetails.exception.description : 'Evaluation exception');
123:     }
124:     return res.result ? res.result.value : undefined;
125:   }
