(async () => {
  const pages = await fetch("http://192.168.1.15:9998/json").then(r => r.json());
  const target = pages.find(p => p.url && p.url.includes("com.cinejoy.tv"));
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise(res => ws.onopen = res);
  let id = 1; const pending = new Map();
  ws.onmessage = (event) => {
    const msg = JSON.parse(event.data);
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) reject(new Error(JSON.stringify(msg.error)));
      else resolve(msg.result);
    }
  };
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const msgId = id++;
    pending.set(msgId, { resolve, reject });
    ws.send(JSON.stringify({ id: msgId, method, params }));
  });
  await send("Runtime.enable");

  // Switch to player view and load stream
  const startRes = await send("Runtime.evaluate", {
    expression: `(() => {
      CinejoyApp.switchView("player");
      return PlayerController.loadStream({ tmdbId: 550, title: "Fight Club", type: "movie" });
    })()`,
    awaitPromise: true,
    returnByValue: true
  });
  console.log("loadStream result:", startRes);

  // Poll video status for 8 seconds
  for (let i = 0; i < 8; i++) {
    await new Promise(r => setTimeout(r, 1000));
    const status = await send("Runtime.evaluate", {
      expression: `(() => {
        const v = document.getElementById("main-video-player");
        return {
          currentTime: v.currentTime,
          duration: v.duration,
          paused: v.paused,
          readyState: v.readyState,
          videoWidth: v.videoWidth,
          videoHeight: v.videoHeight,
          bufferedEnd: v.buffered.length > 0 ? v.buffered.end(v.buffered.length - 1) : 0,
          state: PlayerController.state
        };
      })()`,
      returnByValue: true
    });
    console.log(`Sec ${i+1}:`, status.result.value);
    if (status.result.value.readyState >= 3 && status.result.value.currentTime > 0) {
      break;
    }
  }
  ws.close();
})();
'

