    expression: "({ proxyBaseUrl: window.CINEJOY_CONFIG.proxyBaseUrl, source: window.CINEJOY_CONFIG.proxySource, override: window.CINEJOY_CONFIG.hasExplicitProxyOverride })",
    returnByValue: true
  });
  console.log("Restored Config:", res.result.value);
  ws.close();
})();
'

