/**
 * CineJoy Production On-Device TV Verification & Dynamic Rollback Suite (Prod-4 & Prod-5)
 * Target: LG 32LR686BPSA (webOS 8.5.0 / webOS 23, Firmware 13.50.44, IP: 192.168.1.15)
 * Application: com.cinejoy.tv
 * Service: com.cinejoy.tv.service
 * Runtime: Linux 5.4.96 aarch64, Node.js v12.22.2 (V8 7.8), Chromium 94 WAM
 */

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// Configuration
const CONFIG = {
  tvIp: '192.168.1.15',
  sshPort: '9922',
  sshUser: 'prisoner',
  sshKey: '/home/prem/.ssh/lg-tv_webos_rsa',
  sshKeyFallback: '/home/prem/.ssh/lg-tv_webos_decrypted',
  devtoolsPort: 9998,
  aresDevice: 'lg-tv',
  servicePort: 8088,
  appId: 'com.cinejoy.tv',
  serviceId: 'com.cinejoy.tv.service',
  maxRssMb: 50.0,
  minFreeRamMb: 200.0,
  expectedBackupSha256: 'd0da46ca4e615ff6282b32ea3fbc62dbf9b2c6061961cd9f593a7ef76dc6624b',
  rollbackProxyUrl: 'http://192.168.1.6:8088',
  defaultProxyUrl: 'http://127.0.0.1:8088'
};

// ANSI Color Helpers
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  dim: '\x1b[2m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
  red: '\x1b[31m',
  magenta: '\x1b[35m'
};

function banner(title) {
  const line = '═'.repeat(72);
  console.log(`\n${C.cyan}${C.bold}${line}`);
  console.log(`   ${title}`);
  console.log(`${line}${C.reset}\n`);
}

function pass(msg, durationMs) {
  const d = durationMs !== undefined ? ` ${C.dim}(${durationMs}ms)${C.reset}` : '';
  console.log(`  ${C.green}✔ PASS${C.reset} ${msg}${d}`);
}

function fail(msg, err) {
  console.error(`  ${C.red}✖ FAIL${C.reset} ${msg}`);
  if (err) console.error(`    ${C.red}${err.stack || err}${C.reset}`);
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

// SSH Execution Helper
function execSsh(remoteCmd) {
  const activeKey = fs.existsSync(CONFIG.sshKey) ? CONFIG.sshKey : CONFIG.sshKeyFallback;
  const stdout = execSync(
    `ssh -tt -p ${CONFIG.sshPort} -i ${activeKey} -o HostKeyAlgorithms=+ssh-rsa -o PubkeyAcceptedKeyTypes=+ssh-rsa -o StrictHostKeyChecking=no -o ConnectTimeout=10 ${CONFIG.sshUser}@${CONFIG.tvIp} "${remoteCmd.replace(/"/g, '\\"')}"`,
    { encoding: 'utf8', timeout: 30000 }
  );
  return stdout;
}

// CDP WebSocket Client
class CdpClient {
  constructor(wsUrl) {
    this.wsUrl = wsUrl;
    this.ws = null;
    this.id = 1;
    this.pending = new Map();
    this.eventListeners = new Map();
  }

  connect() {
    return new Promise((resolve, reject) => {
      this.ws = new WebSocket(this.wsUrl);
      this.ws.onopen = () => resolve();
      this.ws.onerror = (err) => reject(err);
      this.ws.onclose = () => {
        for (const [id, { reject: rej }] of this.pending.entries()) {
          rej(new Error('WebSocket closed'));
        }
        this.pending.clear();
      };
      this.ws.onmessage = (event) => {
        try {
          const msg = JSON.parse(event.data);
          if (msg.id && this.pending.has(msg.id)) {
            const { resolve: res, reject: rej } = this.pending.get(msg.id);
            this.pending.delete(msg.id);
            if (msg.error) rej(new Error(msg.error.message || JSON.stringify(msg.error)));
            else res(msg.result);
          } else if (msg.method) {
            const handlers = this.eventListeners.get(msg.method) || [];
            handlers.forEach(fn => fn(msg.params));
          }
        } catch (e) {
          console.error('CDP message parse error:', e);
        }
      };
    });
  }

  send(method, params = {}) {
    return new Promise((resolve, reject) => {
      if (!this.ws || this.ws.readyState !== 1) {
        return reject(new Error('WebSocket is not open'));
      }
      const msgId = this.id++;
      this.pending.set(msgId, { resolve, reject });
      this.ws.send(JSON.stringify({ id: msgId, method, params }));
    });
  }

  on(method, handler) {
    if (!this.eventListeners.has(method)) {
      this.eventListeners.set(method, []);
    }
    this.eventListeners.get(method).push(handler);
  }

  async evaluate(expression, awaitPromise = true) {
    const res = await this.send('Runtime.evaluate', {
      expression,
      awaitPromise,
      returnByValue: true
    });
    if (res.exceptionDetails) {
      throw new Error(
        res.exceptionDetails.exception
          ? (res.exceptionDetails.exception.description || res.exceptionDetails.exception.value)
          : 'Evaluation exception'
      );
    }
    return res.result ? res.result.value : undefined;
  }

  close() {
    if (this.ws) {
      try { this.ws.close(); } catch (_) {}
      this.ws = null;
    }
  }
}

// Helper to discover and connect to WAM CDP target
async function connectToWam(appId = CONFIG.appId, maxRetries = 12, delayMs = 1000) {
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      const pages = await fetch(`http://${CONFIG.tvIp}:${CONFIG.devtoolsPort}/json`).then(r => r.json());
      const target = pages.find(p => p.url && p.url.includes(appId));
      if (target && target.webSocketDebuggerUrl) {
        const client = new CdpClient(target.webSocketDebuggerUrl);
        await client.connect();
        await client.send('Runtime.enable');
        await client.send('Page.enable');
        return { client, target };
      }
    } catch (_) {}
    if (attempt < maxRetries) await sleep(delayMs);
  }
  throw new Error(`Failed to connect to WAM DevTools target for ${appId} after ${maxRetries} attempts`);
}

// Helper to wait for seek completion
async function waitForSeekCompletion(cdpClient, timeoutMs = 12000) {
  const t0 = Date.now();
  while (Date.now() - t0 < timeoutMs) {
    const status = await cdpClient.evaluate(`(() => {
      const v = document.getElementById("main-video-player");
      return {
        currentTime: v.currentTime,
        paused: v.paused,
        seeking: v.seeking,
        readyState: v.readyState,
        bufferedEnd: v.buffered.length > 0 ? v.buffered.end(v.buffered.length - 1) : 0
      };
    })()`);
    if (!status.seeking && status.readyState >= 3) {
      return status;
    }
    await sleep(400);
  }
  return await cdpClient.evaluate(`(() => {
    const v = document.getElementById("main-video-player");
    return {
      currentTime: v.currentTime,
      paused: v.paused,
      seeking: v.seeking,
      readyState: v.readyState,
      bufferedEnd: v.buffered.length > 0 ? v.buffered.end(v.buffered.length - 1) : 0
    };
  })()`);
}

// Main Test Suite
async function runSuite() {
  banner('CINEJOY PRODUCTION ON-DEVICE VERIFICATION & BENCHMARKING (PROD-4 & PROD-5)');

  let cdp = null;
  const results = [];
  const testResultsData = {
    timestamp: new Date().toISOString(),
    suite: 'Cinejoy TV Production Verification & Rollback',
    target: {},
    checks: [],
    metrics: {},
    summary: {}
  };

  const suiteStartTime = Date.now();

  async function check(num, name, fn) {
    const t0 = Date.now();
    try {
      const data = await fn();
      const elapsed = Date.now() - t0;
      pass(`[${num}] ${name}`, elapsed);
      results.push({ num, name, passed: true, elapsed, data });
      testResultsData.checks.push({ num, name, passed: true, elapsed, data });
      return data;
    } catch (err) {
      const elapsed = Date.now() - t0;
      fail(`[${num}] ${name}`, err);
      results.push({ num, name, passed: false, elapsed, error: err.message });
      testResultsData.checks.push({ num, name, passed: false, elapsed, error: err.message });
      throw err;
    }
  }

  try {
    // -------------------------------------------------------------------------
    // Check 1: Target Device Profile & Ares CLI Verification
    // -------------------------------------------------------------------------
    await check(1, 'Target Device Profile & Ares CLI Verification', async () => {
      const devOutput = execSync(`ares-device -i -d ${CONFIG.aresDevice}`, { encoding: 'utf8' });
      const devLines = devOutput.trim().split('\n');
      const devInfo = {};
      devLines.forEach(l => {
        const parts = l.split(':');
        if (parts.length >= 2) devInfo[parts[0].trim()] = parts.slice(1).join(':').trim();
      });

      if (!devInfo.modelName || !devInfo.modelName.includes('32LR686BPSA')) {
        throw new Error(`Unexpected modelName: ${devInfo.modelName}`);
      }
      if (!devInfo.sdkVersion || !devInfo.sdkVersion.includes('8.5.0')) {
        throw new Error(`Unexpected sdkVersion: ${devInfo.sdkVersion}`);
      }
      if (!devInfo.firmwareVersion || !devInfo.firmwareVersion.includes('13.50.44')) {
        throw new Error(`Unexpected firmwareVersion: ${devInfo.firmwareVersion}`);
      }

      testResultsData.target = devInfo;
      console.log(`     Model: ${devInfo.modelName} | SDK: ${devInfo.sdkVersion} | Firmware: ${devInfo.firmwareVersion}`);
      return devInfo;
    });

    // -------------------------------------------------------------------------
    // Check 2: Service Process & Luna Status Verification (Test 1)
    // -------------------------------------------------------------------------
    let initialServicePid = null;
    await check(2, 'Service Process & Luna Status Verification (PID & Luna Status)', async () => {
      const lunaOut = execSsh(`luna-send-pub -i -n 1 luna://${CONFIG.serviceId}/status '{}'`);
      const jsonStart = lunaOut.indexOf('{');
      const jsonEnd = lunaOut.lastIndexOf('}');
      if (jsonStart === -1 || jsonEnd === -1) {
        throw new Error(`No JSON returned from luna-send-pub: ${lunaOut}`);
      }
      const statusRes = JSON.parse(lunaOut.slice(jsonStart, jsonEnd + 1).trim());

      if (statusRes.returnValue !== true) throw new Error(`Service returned returnValue !== true: ${JSON.stringify(statusRes)}`);
      if (statusRes.status !== 'running') throw new Error(`Service status is not 'running': ${statusRes.status}`);
      if (statusRes.port !== CONFIG.servicePort) throw new Error(`Service port mismatch: ${statusRes.port}`);
      if (statusRes.serviceId !== CONFIG.serviceId) throw new Error(`ServiceId mismatch: ${statusRes.serviceId}`);
      if (typeof statusRes.uptime !== 'number' || statusRes.uptime <= 0) throw new Error(`Invalid uptime: ${statusRes.uptime}`);

      const pidOut = execSsh(`pidof ${CONFIG.serviceId}`);
      const pidMatch = pidOut.match(/\b\d+\b/);
      if (!pidMatch) throw new Error(`Could not find running PID for ${CONFIG.serviceId}`);
      initialServicePid = pidMatch[0];

      const rssMb = (statusRes.rssBytes / (1024 * 1024)).toFixed(2);
      console.log(`     PID: ${initialServicePid} | Status: ${statusRes.status} | Port: ${statusRes.port} | Uptime: ${Math.round(statusRes.uptime)}s | RSS: ${rssMb} MB`);
      return { statusRes, pid: initialServicePid };
    });

    // -------------------------------------------------------------------------
    // Check 3: WAM DevTools Discovery & WebSocket CDP Connection
    // -------------------------------------------------------------------------
    let prodTarget = null;
    await check(3, 'WAM DevTools Discovery & WebSocket CDP Connection', async () => {
      const conn = await connectToWam(CONFIG.appId);
      cdp = conn.client;
      prodTarget = conn.target;

      const pageState = await cdp.evaluate(`({
        title: document.title,
        url: window.location.href,
        ready: document.readyState
      })`);

      if (!pageState.title.includes('Cinejoy')) {
        throw new Error(`Unexpected application title: ${pageState.title}`);
      }

      console.log(`     Connected to CDP: "${pageState.title}" (${prodTarget.id}) | URL: ${pageState.url}`);
      return { target: prodTarget, pageState };
    });

    // -------------------------------------------------------------------------
    // Check 4: WAM Loopback HTTP Communication (127.0.0.1:8088/health) (Test 2)
    // -------------------------------------------------------------------------
    await check(4, 'WAM Loopback HTTP Communication: fetch http://127.0.0.1:8088/health', async () => {
      const healthData = await cdp.evaluate(`
        fetch("http://127.0.0.1:${CONFIG.servicePort}/health", { cache: "no-store" })
          .then(r => {
            if (!r.ok) throw new Error("HTTP " + r.status);
            return r.json();
          })
      `);

      if (healthData.status !== 'ok') throw new Error(`Health status not 'ok': ${JSON.stringify(healthData)}`);
      if (healthData.mode !== 'on-device-service') throw new Error(`Unexpected mode: ${healthData.mode}`);
      if (healthData.serviceId !== CONFIG.serviceId) throw new Error(`Unexpected serviceId: ${healthData.serviceId}`);
      if (healthData.port !== CONFIG.servicePort) throw new Error(`Unexpected port: ${healthData.port}`);
      if (!healthData.memory || typeof healthData.memory.rss !== 'number') throw new Error('Missing memory.rss in health response');

      const rssMb = (healthData.memory.rss / (1024 * 1024)).toFixed(2);
      console.log(`     Health: ${healthData.status} | Mode: ${healthData.mode} | Service Uptime: ${Math.round(healthData.uptime)}s | RSS: ${rssMb} MB`);
      return healthData;
    });

    // -------------------------------------------------------------------------
    // Check 5: Movie Catalog Navigation & Poster Loading (Test 3)
    // -------------------------------------------------------------------------
    await check(5, 'Movie Catalog Navigation & Poster Loading (TMDB Trending Movies & Spatial Nav)', async () => {
      const catalogData = await cdp.evaluate(`(() => {
        const trendingShelf = document.getElementById("shelf-trending-movies");
        if (!trendingShelf) throw new Error("Missing #shelf-trending-movies element");

        const cards = Array.from(trendingShelf.querySelectorAll(".card-poster"));
        const posters = cards.map(c => {
          const img = c.querySelector("img");
          return {
            title: c.getAttribute("data-title"),
            year: c.getAttribute("data-year"),
            type: c.getAttribute("data-type"),
            imgSrc: img ? img.src : null,
            imgComplete: img ? img.complete : false,
            imgNaturalWidth: img ? img.naturalWidth : 0
          };
        });

        // Test Spatial Navigation horizontally on shelf
        SpatialNav.setFocus(cards[0]);
        const focus0 = (SpatialNav.getCurrentFocus() === cards[0]);
        SpatialNav.move("right");
        const focusRight = (SpatialNav.getCurrentFocus() === cards[1]);
        SpatialNav.move("left");
        const focusLeft = (SpatialNav.getCurrentFocus() === cards[0]);

        // Test Vertical Navigation down to next shelf
        SpatialNav.move("down");
        const focusDown = SpatialNav.getCurrentFocus();
        const movedToNextShelf = focusDown && focusDown.getAttribute("data-nav-group") === "shelf-trending-series";
        SpatialNav.move("up");
        const returnedToShelf1 = (SpatialNav.getCurrentFocus() === cards[0]);

        const allShelvesCount = document.querySelectorAll(".content-shelf").length;
        const totalCardsCount = document.querySelectorAll(".card-poster").length;

        return {
          cardCount: cards.length,
          posters: posters,
          spatialNav: {
            focus0,
            focusRight,
            focusLeft,
            movedToNextShelf,
            returnedToShelf1
          },
          allShelvesCount,
          totalCardsCount
        };
      })()`);

      if (catalogData.cardCount < 6) {
        throw new Error(`Insufficient trending movie cards: found ${catalogData.cardCount}`);
      }
      const loadedPosters = catalogData.posters.filter(p => p.imgComplete && p.imgNaturalWidth > 0);
      if (loadedPosters.length < 6) {
        throw new Error(`Posters failed to load cleanly: only ${loadedPosters.length}/${catalogData.cardCount} loaded`);
      }
      if (!catalogData.spatialNav.focus0 || !catalogData.spatialNav.focusRight || !catalogData.spatialNav.focusLeft) {
        throw new Error(`Spatial navigation horizontal traversal failed: ${JSON.stringify(catalogData.spatialNav)}`);
      }
      if (!catalogData.spatialNav.movedToNextShelf || !catalogData.spatialNav.returnedToShelf1) {
        throw new Error(`Spatial navigation vertical traversal failed: ${JSON.stringify(catalogData.spatialNav)}`);
      }

      console.log(`     Trending Cards: ${catalogData.cardCount} | Total Cards Across Shelves: ${catalogData.totalCardsCount}`);
      console.log(`     Posters Loaded: ${loadedPosters.length}/${catalogData.cardCount} (TMDB CDN verified: image.tmdb.org)`);
      console.log(`     Spatial Navigation: Horizontal Right/Left & Vertical Down/Up Verified OK`);
      return catalogData;
    });

    // -------------------------------------------------------------------------
    // Check 6: On-Device Stream Resolution via crush.wasm + AES-256-GCM (Test 4)
    // -------------------------------------------------------------------------
    let resolvedMovieStreamUrl = null;
    await check(6, 'On-Device Stream Resolution via crush.wasm + AES-256-GCM (Movie & TV Series)', async () => {
      // 1. Movie Resolution (Fight Club - TMDB 550)
      const movieRes = await cdp.evaluate(`
        fetch("http://127.0.0.1:${CONFIG.servicePort}/api/stream?tmdbId=550&type=movie&server=secret", { cache: "no-store" })
          .then(r => {
            if (!r.ok) throw new Error("HTTP " + r.status);
            return r.json();
          })
      `);

      if (!movieRes.success) throw new Error(`Movie stream resolution failed: ${JSON.stringify(movieRes)}`);
      if (!movieRes.streamUrl || !movieRes.streamUrl.startsWith(`http://127.0.0.1:${CONFIG.servicePort}/hls/proxy?url=`)) {
        throw new Error(`Movie streamUrl not routing via local proxy: ${movieRes.streamUrl}`);
      }
      if (!movieRes.originalUrl || !movieRes.originalUrl.includes('lightspeed.st')) {
        throw new Error(`Unexpected movie originalUrl: ${movieRes.originalUrl}`);
      }
      resolvedMovieStreamUrl = movieRes.streamUrl;

      // 2. TV Series Resolution (Game of Thrones S01E01 - TMDB 1399)
      const tvRes = await cdp.evaluate(`
        fetch("http://127.0.0.1:${CONFIG.servicePort}/api/stream?tmdbId=1399&type=tv&season=1&episode=1&server=secret", { cache: "no-store" })
          .then(r => {
            if (!r.ok) throw new Error("HTTP " + r.status);
            return r.json();
          })
      `);

      if (!tvRes.success) throw new Error(`TV stream resolution failed: ${JSON.stringify(tvRes)}`);
      if (!tvRes.streamUrl || !tvRes.streamUrl.startsWith(`http://127.0.0.1:${CONFIG.servicePort}/hls/proxy?url=`)) {
        throw new Error(`TV streamUrl not routing via local proxy: ${tvRes.streamUrl}`);
      }

      console.log(`     Movie Stream Resolved: ${movieRes.streamUrl.slice(0, 75)}...`);
      console.log(`     Movie Subtitles Available: ${movieRes.subtitles ? movieRes.subtitles.length : 0} languages`);
      console.log(`     TV Series Stream Resolved: ${tvRes.streamUrl.slice(0, 75)}...`);
      return { movieRes, tvRes };
    });

    // -------------------------------------------------------------------------
    // Check 7: Live 1080p Video Playback in #main-video-player (Test 5)
    // -------------------------------------------------------------------------
    let playbackMetrics = {};
    await check(7, 'Live 1080p Video Playback in #main-video-player (readyState: 4, duration, buffer)', async () => {
      // Switch view to player and load movie stream
      await cdp.evaluate(`(() => {
        CinejoyApp.switchView("player");
        return PlayerController.loadStream({ tmdbId: 550, title: "Fight Club", type: "movie" });
      })()`);

      // Poll until video is READY or PLAYING with readyState >= 3
      let readyStateReached = false;
      for (let attempt = 0; attempt < 15; attempt++) {
        await sleep(1000);
        const status = await cdp.evaluate(`(() => {
          const v = document.getElementById("main-video-player");
          return {
            readyState: v.readyState,
            paused: v.paused,
            currentTime: v.currentTime,
            duration: v.duration,
            state: PlayerController.state
          };
        })()`);
        if (status.readyState >= 3) {
          readyStateReached = true;
          break;
        }
      }

      if (!readyStateReached) {
        throw new Error('Video did not reach readyState >= 3 within 15 seconds');
      }

      // Ensure playback is unpaused
      await cdp.evaluate('PlayerController.play()');

      // Sample playback progression over 4 seconds
      const t0 = await cdp.evaluate(`(() => {
        const v = document.getElementById("main-video-player");
        return {
          currentTime: v.currentTime,
          duration: v.duration,
          paused: v.paused,
          readyState: v.readyState,
          videoWidth: v.videoWidth,
          videoHeight: v.videoHeight,
          bufferedEnd: v.buffered.length > 0 ? v.buffered.end(v.buffered.length - 1) : 0,
          state: PlayerController.state
        };
      })()`);

      await sleep(3500);

      const t1 = await cdp.evaluate(`(() => {
        const v = document.getElementById("main-video-player");
        return {
          currentTime: v.currentTime,
          duration: v.duration,
          paused: v.paused,
          readyState: v.readyState,
          videoWidth: v.videoWidth,
          videoHeight: v.videoHeight,
          bufferedEnd: v.buffered.length > 0 ? v.buffered.end(v.buffered.length - 1) : 0,
          state: PlayerController.state
        };
      })()`);

      if (t1.readyState < 3) throw new Error(`readyState too low: ${t1.readyState} (expected >= 3)`);
      if (t1.paused) throw new Error('Video player is paused during active playback');
      if (t1.currentTime <= t0.currentTime) {
        throw new Error(`currentTime did not advance: ${t0.currentTime.toFixed(2)}s -> ${t1.currentTime.toFixed(2)}s`);
      }
      if (t1.bufferedEnd <= t1.currentTime) {
        throw new Error(`Buffer not ahead of playback position: pos=${t1.currentTime.toFixed(2)}s, bufEnd=${t1.bufferedEnd.toFixed(2)}s`);
      }
      if (typeof t1.duration !== 'number' || t1.duration <= 0) {
        throw new Error(`Invalid duration: ${t1.duration}`);
      }

      playbackMetrics = { t0, t1 };
      const aheadBuffer = (t1.bufferedEnd - t1.currentTime).toFixed(2);
      console.log(`     Player State: ${t1.state} | readyState: ${t1.readyState} | Duration: ${Math.round(t1.duration)}s`);
      console.log(`     Resolution: ${t1.videoWidth}x${t1.videoHeight} | Current Time: ${t0.currentTime.toFixed(2)}s -> ${t1.currentTime.toFixed(2)}s`);
      console.log(`     Buffer End: ${t1.bufferedEnd.toFixed(2)}s (${aheadBuffer}s ahead of playhead)`);
      return playbackMetrics;
    });

    // -------------------------------------------------------------------------
    // Check 8: Interactive Seeking Forward (+15s) and Backward (-15s) (Test 6)
    // -------------------------------------------------------------------------
    await check(8, 'Interactive Seeking Forward (+15s) & Backward (-15s) with Recovery Timing', async () => {
      // 1. Forward Seek (+15s)
      const tBeforeFwd = await cdp.evaluate('document.getElementById("main-video-player").currentTime');
      const fwdSeekStart = Date.now();

      await cdp.evaluate('PlayerController.seekBy(15)');
      const fwdStatus = await waitForSeekCompletion(cdp, 10000);
      const fwdRecoveryTimeMs = Date.now() - fwdSeekStart;

      if (fwdStatus.currentTime < tBeforeFwd + 8.0) {
        throw new Error(`Forward seek failed: before=${tBeforeFwd.toFixed(2)}s, after=${fwdStatus.currentTime.toFixed(2)}s`);
      }
      if (fwdStatus.readyState < 3) {
        throw new Error(`Playback did not resume cleanly after forward seek: readyState=${fwdStatus.readyState}`);
      }
      if (fwdRecoveryTimeMs > 4000) {
        console.warn(`[Seek Warning] Forward seek recovery took ${fwdRecoveryTimeMs}ms (> 4000ms target)`);
      }

      console.log(`     Forward Seek (+15s): ${tBeforeFwd.toFixed(2)}s -> ${fwdStatus.currentTime.toFixed(2)}s (Recovery: ${fwdRecoveryTimeMs}ms, readyState: ${fwdStatus.readyState})`);

      // Let playback run for 2 seconds
      await sleep(2000);

      // 2. Backward Seek (-15s)
      const tBeforeBwd = await cdp.evaluate('document.getElementById("main-video-player").currentTime');
      const bwdSeekStart = Date.now();

      await cdp.evaluate('PlayerController.seekBy(-15)');
      const bwdStatus = await waitForSeekCompletion(cdp, 10000);
      const bwdRecoveryTimeMs = Date.now() - bwdSeekStart;

      if (bwdStatus.currentTime > tBeforeBwd - 7.0) {
        throw new Error(`Backward seek failed: before=${tBeforeBwd.toFixed(2)}s, after=${bwdStatus.currentTime.toFixed(2)}s`);
      }
      if (bwdStatus.readyState < 3) {
        throw new Error(`Playback did not resume cleanly after backward seek: readyState=${bwdStatus.readyState}`);
      }

      console.log(`     Backward Seek (-15s): ${tBeforeBwd.toFixed(2)}s -> ${bwdStatus.currentTime.toFixed(2)}s (Recovery: ${bwdRecoveryTimeMs}ms, readyState: ${bwdStatus.readyState})`);

      return {
        forward: { tBefore: tBeforeFwd, tAfter: fwdStatus.currentTime, recoveryMs: fwdRecoveryTimeMs },
        backward: { tBefore: tBeforeBwd, tAfter: bwdStatus.currentTime, recoveryMs: bwdRecoveryTimeMs }
      };
    });

    // -------------------------------------------------------------------------
    // Check 9: Triple-Shield Service Persistence Across Playback, Pause, Idle (> 60s) (Test 7)
    // -------------------------------------------------------------------------
    await check(9, 'Triple-Shield Service Persistence Across Playback, Pause & Idle States (> 60s)', async () => {
      const getPidCmd = `pidof ${CONFIG.serviceId}`;
      function getPid() {
        const out = execSsh(getPidCmd);
        const match = out.match(/\b\d+\b/);
        return match ? match[0] : null;
      }

      const initialPid = getPid();
      if (!initialPid) throw new Error('Could not get initial service PID');
      console.log(`     Initial Monitored PID: ${initialPid}`);

      // State A: Active Playback State (15s)
      console.log('     [State A] Active Playback monitoring (15s)...');
      await sleep(15000);
      const pidA = getPid();
      if (pidA !== initialPid) throw new Error(`Service PID changed during active playback: ${initialPid} -> ${pidA}`);

      // State B: Paused State (15s)
      console.log('     [State B] Paused State monitoring (15s)...');
      await cdp.evaluate('PlayerController.pause()');
      await sleep(15000);
      const pidB = getPid();
      if (pidB !== initialPid) throw new Error(`Service PID changed during pause: ${initialPid} -> ${pidB}`);

      const healthPaused = await cdp.evaluate(`
        fetch("http://127.0.0.1:${CONFIG.servicePort}/health", { cache: "no-store" }).then(r => r.json())
      `);
      if (healthPaused.status !== 'ok') throw new Error('Service health check failed during pause state');

      // State C: Stopped / Idle State (20s)
      console.log('     [State C] Stopped / Idle State monitoring (20s)...');
      await cdp.evaluate(`(() => {
        PlayerController.stop();
        const v = document.getElementById("main-video-player");
        v.pause();
        v.removeAttribute("src");
        v.load();
      })()`);
      await sleep(20000);
      const pidC = getPid();
      if (pidC !== initialPid) throw new Error(`Service PID changed during idle state: ${initialPid} -> ${pidC}`);

      const healthIdle = await cdp.evaluate(`
        fetch("http://127.0.0.1:${CONFIG.servicePort}/health", { cache: "no-store" }).then(r => r.json())
      `);
      if (healthIdle.status !== 'ok') throw new Error('Service health check failed during idle state');

      // State D: Home View Navigation (15s)
      console.log('     [State D] Home View navigation monitoring (15s)...');
      await cdp.evaluate('CinejoyApp.switchView("home")');
      await sleep(15000);
      const pidD = getPid();
      if (pidD !== initialPid) throw new Error(`Service PID changed during home navigation: ${initialPid} -> ${pidD}`);

      const totalMonitoredSeconds = 15 + 15 + 20 + 15; // 65 seconds
      console.log(`     Total Monitored Persistence: ${totalMonitoredSeconds}s (> 60s requirement satisfied)`);
      console.log(`     Service Process Kept Alive Continuously (PID: ${initialPid}, Uptime: ${Math.round(healthIdle.uptime)}s)`);

      return {
        initialPid,
        finalPid: pidD,
        totalMonitoredSeconds,
        serviceUptime: healthIdle.uptime
      };
    });

    // -------------------------------------------------------------------------
    // Check 10: TV Physical Memory & CPU Profiling (Test 8)
    // -------------------------------------------------------------------------
    await check(10, 'TV Physical Memory & CPU Profiling (VmRSS < 50MB, Free RAM > 200MB)', async () => {
      const pidOut = execSsh(`pidof ${CONFIG.serviceId}`);
      const pid = (pidOut.match(/\b\d+\b/) || [])[0];
      if (!pid) throw new Error('Could not find PID for memory profiling');

      const procStatus = execSsh(`cat /proc/${pid}/status`);
      const freeMem = execSsh('free -m');

      const metrics = {};
      procStatus.split('\n').forEach(line => {
        const parts = line.split(':');
        if (parts.length >= 2) {
          metrics[parts[0].trim()] = parts.slice(1).join(':').trim();
        }
      });

      const vmRssKb = parseInt(metrics['VmRSS'] || '0', 10);
      const vmRssMb = vmRssKb / 1024;
      const vmSizeMb = parseInt(metrics['VmSize'] || '0', 10) / 1024;
      const vmPeakMb = parseInt(metrics['VmPeak'] || '0', 10) / 1024;
      const vmHwmMb = parseInt(metrics['VmHWM'] || '0', 10) / 1024;
      const threads = metrics['Threads'];

      if (vmRssMb > CONFIG.maxRssMb) {
        throw new Error(`VmRSS (${vmRssMb.toFixed(2)} MB) exceeded safe budget of ${CONFIG.maxRssMb} MB`);
      }

      // Parse free -m available RAM
      let availableRamMb = 0;
      freeMem.split('\n').forEach(line => {
        if (line.startsWith('Mem:')) {
          const cols = line.trim().split(/\s+/);
          // Columns: Mem: total used free shared buff/cache available
          if (cols.length >= 7) availableRamMb = parseInt(cols[6], 10);
          else if (cols.length >= 4) availableRamMb = parseInt(cols[3], 10);
        }
      });

      if (availableRamMb < CONFIG.minFreeRamMb) {
        throw new Error(`TV available RAM (${availableRamMb} MB) below safe margin of ${CONFIG.minFreeRamMb} MB`);
      }

      console.log(`     Service PID: ${pid} | Threads: ${threads}`);
      console.log(`     VmRSS: ${vmRssMb.toFixed(2)} MB (Limit: < ${CONFIG.maxRssMb} MB) | VmHWM: ${vmHwmMb.toFixed(2)} MB`);
      console.log(`     VmSize: ${vmSizeMb.toFixed(2)} MB | VmPeak: ${vmPeakMb.toFixed(2)} MB`);
      console.log(`     System Available RAM: ${availableRamMb} MB (Limit: > ${CONFIG.minFreeRamMb} MB)`);

      testResultsData.metrics = {
        pid,
        threads,
        vmRssMb,
        vmHwmMb,
        vmSizeMb,
        vmPeakMb,
        availableRamMb,
        freeMemOutput: freeMem.trim()
      };
      return testResultsData.metrics;
    });

    // -------------------------------------------------------------------------
    // Check 11: Milestone Prod-5 Dynamic Rollback Parameter Override
    // -------------------------------------------------------------------------
    await check(11, 'Milestone Prod-5: Dynamic Rollback Parameter Override (-p proxyUrl)', async () => {
      if (cdp) cdp.close();

      console.log('     Closing app and launching with dynamic rollback parameters...');
      execSync(`ares-launch -c -d ${CONFIG.aresDevice} ${CONFIG.appId}`);
      await sleep(1500);
      execSync(`ares-launch -d ${CONFIG.aresDevice} -p '{"proxyUrl":"${CONFIG.rollbackProxyUrl}"}' ${CONFIG.appId}`);
      await sleep(2000);

      const conn = await connectToWam(CONFIG.appId);
      cdp = conn.client;

      const dynamicConfig = await cdp.evaluate(`({
        proxyBaseUrl: window.CINEJOY_CONFIG.proxyBaseUrl,
        proxySource: window.CINEJOY_CONFIG.proxySource,
        hasExplicitProxyOverride: window.CINEJOY_CONFIG.hasExplicitProxyOverride,
        launchParams: window.PalmSystem ? window.PalmSystem.launchParams : null
      })`);

      if (dynamicConfig.proxyBaseUrl !== CONFIG.rollbackProxyUrl) {
        throw new Error(`proxyBaseUrl was not overridden dynamically: expected ${CONFIG.rollbackProxyUrl}, got ${dynamicConfig.proxyBaseUrl}`);
      }
      if (dynamicConfig.hasExplicitProxyOverride !== true) {
        throw new Error(`hasExplicitProxyOverride is false: expected true`);
      }
      if (dynamicConfig.proxySource !== 'launchParams') {
        throw new Error(`proxySource mismatch: expected 'launchParams', got '${dynamicConfig.proxySource}'`);
      }

      console.log(`     Dynamic Config Applied: proxyBaseUrl -> ${dynamicConfig.proxyBaseUrl}`);
      console.log(`     Proxy Source: ${dynamicConfig.proxySource} | Explicit Override: ${dynamicConfig.hasExplicitProxyOverride}`);
      console.log('     Dynamic parameter override succeeded without requiring an IPK rebuild.');
      return dynamicConfig;
    });

    // -------------------------------------------------------------------------
    // Check 12: Milestone Prod-5 Default On-Device Proxy Recovery
    // -------------------------------------------------------------------------
    await check(12, 'Milestone Prod-5: Restore Default On-Device Proxy Launch', async () => {
      if (cdp) cdp.close();

      console.log('     Closing app and launching with default on-device configuration...');
      execSync(`ares-launch -c -d ${CONFIG.aresDevice} ${CONFIG.appId}`);
      await sleep(1500);
      execSync(`ares-launch -d ${CONFIG.aresDevice} ${CONFIG.appId}`);
      await sleep(2000);

      const conn = await connectToWam(CONFIG.appId);
      cdp = conn.client;

      const restoredConfig = await cdp.evaluate(`({
        proxyBaseUrl: window.CINEJOY_CONFIG.proxyBaseUrl,
        proxySource: window.CINEJOY_CONFIG.proxySource,
        hasExplicitProxyOverride: window.CINEJOY_CONFIG.hasExplicitProxyOverride
      })`);

      if (restoredConfig.proxyBaseUrl !== CONFIG.defaultProxyUrl) {
        throw new Error(`Default proxyBaseUrl was not restored: expected ${CONFIG.defaultProxyUrl}, got ${restoredConfig.proxyBaseUrl}`);
      }
      if (restoredConfig.hasExplicitProxyOverride !== false) {
        throw new Error(`hasExplicitProxyOverride is true: expected false`);
      }
      if (restoredConfig.proxySource !== 'default') {
        throw new Error(`proxySource mismatch: expected 'default', got '${restoredConfig.proxySource}'`);
      }

      console.log(`     Restored Default Config: proxyBaseUrl -> ${restoredConfig.proxyBaseUrl}`);
      console.log(`     Proxy Source: ${restoredConfig.proxySource} | Explicit Override: ${restoredConfig.hasExplicitProxyOverride}`);
      console.log('     Default on-device localhost proxy restored instantly.');
      return restoredConfig;
    });

    // -------------------------------------------------------------------------
    // Check 13: Milestone Prod-5 Backup Package Integrity Verification
    // -------------------------------------------------------------------------
    await check(13, 'Milestone Prod-5: Backup Package Integrity Verification (SHA-256)', async () => {
      const backupPath = path.resolve(__dirname, '..', 'dist', 'com.cinejoy.tv_1.0.0_all.ipk.bak');
      const currentPath = path.resolve(__dirname, '..', 'dist', 'com.cinejoy.tv_1.0.0_all.ipk');

      if (!fs.existsSync(backupPath)) {
        throw new Error(`Backup IPK not found at: ${backupPath}`);
      }
      if (!fs.existsSync(currentPath)) {
        throw new Error(`Current IPK not found at: ${currentPath}`);
      }

      const backupBuffer = fs.readFileSync(backupPath);
      const backupSha256 = crypto.createHash('sha256').update(backupBuffer).digest('hex');

      const currentBuffer = fs.readFileSync(currentPath);
      const currentSha256 = crypto.createHash('sha256').update(currentBuffer).digest('hex');

      if (backupSha256 !== CONFIG.expectedBackupSha256) {
        throw new Error(`Backup IPK SHA-256 mismatch: expected ${CONFIG.expectedBackupSha256}, calculated ${backupSha256}`);
      }

      console.log(`     Backup Package: dist/com.cinejoy.tv_1.0.0_all.ipk.bak (${backupBuffer.length} bytes)`);
      console.log(`     Backup SHA-256: ${backupSha256} (Verified OK)`);
      console.log(`     Current Package: dist/com.cinejoy.tv_1.0.0_all.ipk (${currentBuffer.length} bytes)`);
      console.log(`     Current SHA-256: ${currentSha256}`);

      return {
        backup: { path: backupPath, size: backupBuffer.length, sha256: backupSha256, verified: true },
        current: { path: currentPath, size: currentBuffer.length, sha256: currentSha256 }
      };
    });

    if (cdp) cdp.close();

    // Summary calculation
    const totalElapsed = Date.now() - suiteStartTime;
    const passedCount = testResultsData.checks.filter(c => c.passed).length;
    testResultsData.summary = {
      totalChecks: testResultsData.checks.length,
      passedChecks: passedCount,
      failedChecks: testResultsData.checks.length - passedCount,
      passRate: ((passedCount / testResultsData.checks.length) * 100).toFixed(1) + '%',
      totalElapsedMs: totalElapsed
    };

    // Ensure reports directory exists and export results JSON
    const reportsDir = path.resolve(__dirname, '..', 'reports');
    if (!fs.existsSync(reportsDir)) fs.mkdirSync(reportsDir, { recursive: true });
    const resultsPath = path.join(reportsDir, 'tv-prod-verification-results.json');
    fs.writeFileSync(resultsPath, JSON.stringify(testResultsData, null, 2), 'utf8');

    console.log(`\n  ${C.green}✔ Verification telemetry exported to ${resultsPath}${C.reset}`);
    banner(`ALL ${testResultsData.checks.length} PRODUCTION ON-DEVICE VERIFICATION CHECKS PASSED (100% SUCCESS)`);

  } catch (err) {
    if (cdp) cdp.close();
    banner('PRODUCTION VERIFICATION SUITE ENCOUNTERED FAILURES');
    console.error(err);
    process.exit(1);
  }
}

runSuite().catch(err => {
  console.error('Fatal execution error in test runner:', err);
  process.exit(1);
});

